<section class="admin-head"><div><p class="eyebrow">CMS + SEO · v0.7.8</p><h1>Editorial CMS & Search Architecture</h1><p>Journal, guides, room stories, pages, reusable content blocks, redirects and sitemap-ready publishing.</p></div><a class="btn primary" href="<?=e(url('/admin/cms/new'))?>">New content</a></section>
<section class="admin-card"><h2>Content</h2><div class="table-wrap"><table><thead><tr><th>Title</th><th>Type</th><th>Status</th><th>Route</th><th>Updated</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><a href="<?=e(url('/admin/cms/'.$i['guid']))?>"><?=e($i['title'])?></a></td><td><?=e($i['type'])?></td><td><?=e($i['status'])?></td><td><?=e(cms_content_route($i))?></td><td><?=e(substr($i['updated_at'],0,16))?></td></tr><?php endforeach;?></tbody></table></div></section>
