<section class="admin-card"><h2>Redirect</h2><form method="post" action="<?=e(url('/admin/cms/redirect'))?>" class="stack"><?=csrf_field()?><label>From<input name="from" placeholder="/old-path" required></label><label>To<input name="to" placeholder="/new-path" required></label><label>Code<select name="code"><option>301</option><option>302</option></select></label><button class="btn outline">Add redirect</button></form><ul><?php foreach($redirects as $r):?><li><?=e($r['code'].' '.$r['from'].' → '.$r['to'])?></li><?php endforeach;?></ul></section></div>
